            try:
                response_code, response_data = self.request_func(url)
                if response_code == 200:
                    return response_data
                raise HTTPError(f"HTTP error: {response_code}")
            except HTTPError as http_err:
                status_code = int(http_err.args[0].split()[-1])
                if attempt == self.max_retries - 1 or status_code not in [429, 500, 502, 503, 504]:
